"use strict";App.Pages.GoogleCalendarSettings=function(){function isInvalid(){try{return $("#google-calendar-settings .is-invalid").removeClass("is-invalid"),!1}catch(error){return App.Layouts.Backend.displayNotification(error.message),!0}}function deserialize(googleCalendarSettings){googleCalendarSettings.forEach(function(googleCalendarSetting){var $field=$("[data-field=\""+googleCalendarSetting.name+"\"]");$field.is(":checkbox")?$field.prop("checked",!!+googleCalendarSetting.value):$field.val(googleCalendarSetting.value)})}function serialize(){var googleCalendarSettings=[];return $("[data-field]").each(function(index,field){var $field=$(field);googleCalendarSettings.push({name:$field.data("field"),value:$field.is(":checkbox")?+$field.prop("checked"):$field.val()})}),googleCalendarSettings}function onSaveSettingsClick(){if(isInvalid())return void App.Layouts.Backend.displayNotification(lang("settings_are_invalid"));var googleCalendarSettings=serialize();App.Http.GoogleCalendarSettings.save(googleCalendarSettings).done(function(){App.Layouts.Backend.displayNotification(lang("settings_saved"))})}var $saveSettings=$("#save-settings");return document.addEventListener("DOMContentLoaded",function(){$saveSettings.on("click",onSaveSettingsClick);var googleCalendarSettings=vars("google_calendar_settings");deserialize(googleCalendarSettings)}),{}}();